body:
Running `ptoas --enable-insert-sync` on this pto ir:

```
module {
  func.func @abs_kernel_2d(%arg0: !pto.ptr<f32>, %arg1: !pto.ptr<f32>) {
    %c0 = arith.constant 0 : index
    %c1 = arith.constant 1 : index
    %c32 = arith.constant 32 : index
    %0 = pto.make_tensor_view %arg0, shape = [%c32, %c32] strides = [%c32, %c1] : !pto.tensor_view<2xf32>
    %1 = pto.make_tensor_view %arg1, shape = [%c32, %c32] strides = [%c32, %c1] : !pto.tensor_view<2xf32>
    %2 = pto.subview %0, offsets = [%c0, %c0], sizes = [%c32, %c32] : !pto.tensor_view<2xf32> -> !pto.tile_view<32x32xf32>
    %3 = pto.alloc_tile : <loc=ub, dtype=f32, rows=32, cols=32, v_row=32, v_col=32, blayout=row_major, slayout=none_box, fractal=512, pad=0>
    %4 = pto.alloc_tile : <loc=ub, dtype=f32, rows=32, cols=32, v_row=32, v_col=32, blayout=row_major, slayout=none_box, fractal=512, pad=0>
    pto.tload ins(%2 : !pto.tile_view<32x32xf32>) outs(%3 : !pto.tile_buf<loc=ub, dtype=f32, rows=32, cols=32, v_row=32, v_col=32, blayout=row_major, slayout=none_box, fractal=512, pad=0>)
    pto.tabs ins(%3 : !pto.tile_buf<loc=ub, dtype=f32, rows=32, cols=32, v_row=32, v_col=32, blayout=row_major, slayout=none_box, fractal=512, pad=0>) outs(%4 : !pto.tile_buf<loc=ub, dtype=f32, rows=32, cols=32, v_row=32, v_col=32, blayout=row_major, slayout=none_box, fractal=512, pad=0>)
    %5 = pto.subview %1, offsets = [%c0, %c0], sizes = [%c32, %c32] : !pto.tensor_view<2xf32> -> !pto.tile_view<32x32xf32>
    pto.tstore ins(%4 : !pto.tile_buf<loc=ub, dtype=f32, rows=32, cols=32, v_row=32, v_col=32, blayout=row_major, slayout=none_box, fractal=512, pad=0>) outs(%5 : !pto.tile_view<32x32xf32>)
    return
  }
}
```

gives:

```cpp
#include "common/pto_instr.hpp"
using namespace pto;
__global__ AICORE void abs_kernel_2d(__gm__ float* v1, __gm__ float* v2) {
  unsigned v3 = 1;
  unsigned v4 = 0;
  int32_t v5 = 32;
  int32_t v6 = 1;
  int64_t v7 = 0;
  int64_t v8 = 4096;
  using T = float;
  unsigned v9 = (unsigned) v5;
  unsigned v10 = v4 * v9;
  unsigned v11 = v4 + v10;
  unsigned v12 = (unsigned) v6;
  unsigned v13 = v4 * v12;
  unsigned v14 = v11 + v13;
  __gm__ float* v15 = v1 + v14;
  using GTShape_235076000 = pto::Shape<32, 32>;
  using GTStride_235076000 = pto::Stride<32, 1>;
  GTShape_235076000 v16 = GTShape_235076000();
  GTStride_235076000 v17 = GTStride_235076000();
  using GT_235076000 = GlobalTensor<float, GTShape_235076000, GTStride_235076000>;
  GT_235076000 v18 = GT_235076000(v15, v16, v17);
  Tile<TileType::Vec, float, 32, 32, BLayout::RowMajor, 32, 32, SLayout::NoneBox, 512, PadValue::Null> v19;
  TASSIGN(v19, v7);
  Tile<TileType::Vec, float, 32, 32, BLayout::RowMajor, 32, 32, SLayout::NoneBox, 512, PadValue::Null> v20;
  TASSIGN(v20, v8);
  TLOAD(v19, v18);
  TABS(v20, v19);
  unsigned v21 = (unsigned) v5;
  unsigned v22 = v4 * v21;
  unsigned v23 = v4 + v22;
  unsigned v24 = (unsigned) v6;
  unsigned v25 = v4 * v24;
  unsigned v26 = v23 + v25;
  __gm__ float* v27 = v2 + v26;
  using GTShape_235076176 = pto::Shape<32, 32>;
  using GTStride_235076176 = pto::Stride<32, 1>;
  GTShape_235076176 v28 = GTShape_235076176();
  GTStride_235076176 v29 = GTStride_235076176();
  using GT_235076176 = GlobalTensor<float, GTShape_235076176, GTStride_235076176>;
  GT_235076176 v30 = GT_235076176(v27, v28, v29);
  TSTORE(v30, v20);
  pipe_barrier(PIPE_ALL);
  return;
}
```

Compare to without `--enable-insert-sync`, the only difference is additional `pipe_barrier(PIPE_ALL);` at the end. Missing `set` & `wait` between `TLOAD`, `TABS`, `TSTORE`.

Reproduced by the docker image at https://github.com/zhangstevenunity/PTOAS/pull/9

```bash
docker run --rm -it ptoas:py3.11 /bin/bash
cd /test/Abs
python ./abs.py > ./abs.pto
ptoas --enable-insert-sync ./abs.pto -o ./abs.cpp
```

Currently`cfg = pto.TileBufConfigAttr.get(bl, sl, 512, pd, ctx)` is hard-coded everywhere in the test samples. Better expose `pto.TileConfig.fractalABSize = 512` that matches the [cpp header](https://gitcode.com/cann/pto-isa/blob/8.5.0/include/pto/common/pto_tile.hpp#L720-L730):

```cpp 
namespace TileConfig {
static constexpr int alignedSize = 32;
static constexpr int fixedRowSize = 16;
static constexpr int fixedColSize = 16;
static constexpr int fixedMxRowSize = 16;
static constexpr int fixedMxColSize = 2;
static constexpr int fractalABSize = 512;
static constexpr int fractalCSize = 1024;
static constexpr int fractalMxSize = 32;
} // namespace TileConfig
```

