    GlobalTensor<int32_t, pto::Shape<1, 1, 1, 1, 8>, pto::Stride<8, 8, 8, 8, 1>, pto::Layout::ND>(
        v4 + (v14 + v14 * (unsigned) v16 + v14 * (unsigned) v18), v30, v31);
int32_t v33 = v32.GetValue(
    (int32_t) ((uint32_t) ((int32_t) (uint32_t) v29 * (uint32_t) v8) + (uint32_t) v6));
```

## Expected Generated Code

```cpp
